return function(B,test)
 local M=require('desktop_model');local V=require('vessels');local T=require('desktop_samples');local C=require('desktop_controls');local Host=require('desktop_host');local Art=require('desktop_art');local G=require('genome');local S=require('persistence');local Store=require('desktop_store')
 local function fixture()
  local s=B.new(20261112);B.collect(s);V.ensure(s);M.ensure(s);require('desktop_worlds').ensure(s)
  local a=s.vessels[5];assert(T.seed(s,a.id,1));assert(V.add(s,4,true));local b=s.vessels[#s.vessels];assert(T.seed(s,b.id,1))
  return s,a,b,M.add(s,'vial',a.id),M.add(s,'vial',b.id)
 end
 local function withState(s,fn)
  local prior,monitors,testing=Host.context,Host.monitors,Host.testing
  Host.context={getState=function() return s end,msg=function() end};Host.monitors={{id='test',x=0,y=0,w=1920,h=1080,dpi=96}};Host.testing=true
  local ok,why=xpcall(fn,debug.traceback);Host.context=prior;Host.monitors=monitors;Host.testing=testing;assert(ok,why)
 end
 local function draw(s,o) C.expand(s,o);Art.render(s,o,1);return C.hits[o.id] end
 local function action(s,o,label) draw(s,o);for _,hit in ipairs(C.hits[o.id]) do if hit.id==label then hit.fn();return end end;error('Missing container action '..label) end
 test('Each container panel is fixed to its own ID, with no inventory or vial selectors',function()
  local s,a,b,oa,ob=fixture();withState(s,function() local before=S.encode(s.vessels);for _,o in ipairs({oa,ob}) do local hits=draw(s,o);assert(o.w==440);for _,h in ipairs(hits) do assert(not h.id:find('>') and not h.id:find('Loose cell') and not h.id:find('Introduce') and not h.id:find('Source:'),'Global selector leaked into container: '..h.id) end end;assert(oa.entityId==a.id and ob.entityId==b.id and S.encode(s.vessels)==before)
   local _,data=Art.render(s,oa,1);local base=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local file=assert(io.open(base..'/desktop-container-preview.png','wb'));file:write(data:encode('png'):getString());file:close()
  end)
 end)
 test('Changing one vial through its buttons leaves another vial unchanged',function()
  local s,a,b,oa,ob=fixture();withState(s,function() draw(s,ob);local other=S.encode(b);action(s,oa,'Close cap / lid');assert(a.closed and S.encode(b)==other);action(s,oa,'Open cap / lid');action(s,oa,'Take sample');assert(V.count(a)==0 and s.desktop.pipette.sample.sourceContainerId==a.id and S.encode(b)==other);assert(T.dispense(s,a.id));assert(V.count(a)==1 and S.encode(b)==other) end)
 end)
 test('ID-bound vial operations survive vessel list reordering',function()
  local s,a,b,oa=fixture();assert(V.add(s,5,true));local cryo=s.vessels[#s.vessels];assert(T.seed(s,cryo.id,1));local o=M.add(s,'cryovial',cryo.id)
  withState(s,function() draw(s,o);local freeze;for _,h in ipairs(C.hits[o.id]) do if h.id=='Freeze this vial' then freeze=h.fn end end;assert(freeze);local other=S.encode(b);for i=1,math.floor(#s.vessels/2) do local j=#s.vessels-i+1;s.vessels[i],s.vessels[j]=s.vessels[j],s.vessels[i] end;freeze();assert(cryo.frozen and not a.frozen and S.encode(b)==other) end)
 end)
 test('Deleted container actions fail safely instead of falling through to another vial',function()
  local s,a,b=fixture();for i,v in ipairs(s.vessels) do if v.id==a.id then table.remove(s.vessels,i);break end end;local other=S.encode(b);assert(not T.action(s,a.id,'freeze'));assert(not T.collect(s,a.id));assert(S.encode(b)==other)
 end)
 test('DNA vials show one fixed record and send that exact DNA to the Forge',function()
  local s=fixture();assert(B.extract(s,1));assert(B.extract(s,2));local first,second=s.materials[1],s.materials[2];local oa=M.add(s,'dna',first.id);local ob=M.add(s,'dna',second.id);local forge=M.add(s,'forge','forge')
  withState(s,function() local before=S.encode(s.materials);for _,o in ipairs({oa,ob}) do local hits=draw(s,o);assert(#hits==2 and hits[2].id=='Use this DNA in the Forge') end;action(s,ob,'Use this DNA in the Forge');assert(G.hash(require('genome_editor').draft)==G.hash(second.genome));assert(forge.config.sourceType=='materials' and forge.config.source==2);assert(S.encode(s.materials)==before and oa.entityId==first.id and ob.entityId==second.id) end)
 end)
 test('Container isolation, labels and contents persist through save restoration',function()
  local s,a,b,oa,ob=fixture();a.label='Vial A';b.label='Vial B';a.closed=true;b.temperature=31;local beforeA,beforeB=S.encode(a),S.encode(b)
  local restored=assert(Store.decode(Store.payload(s,123456),B));assert(S.encode(T.vessel(restored,a.id))==beforeA and S.encode(T.vessel(restored,b.id))==beforeB);assert(M.find(restored,oa.id).entityId==a.id and M.find(restored,ob.id).entityId==b.id)
 end)
 test('Old container browser settings migrate without changing biological records',function()
  local s,a,b,o=fixture();o.config={expanded=true,collapsed={w=94,h=190},cell=6,source=2,vessel=3};o.w=640;o.h=450;local before=S.encode(s.vessels);C.prepare(o);assert(o.w==440 and o.h==354 and o.config.cell==nil and o.config.source==nil and o.config.vessel==nil);assert(o.entityId==a.id and S.encode(s.vessels)==before)
 end)
end
